/* ───────────── full-site templates ───────────── */
const pageJson = (children) => ({ schemaVersion: 2, settings: {}, root: { id: "root", type: "Page", props: {}, children } });
const themeOf = (presetKey) => THEME_PRESETS.find((p) => p.key === presetKey)?.theme || DEFAULT_THEME;
/** A page wrapped with the site's navigation bar and footer. */
const page = (ref, title, path, sections, opts = {}) => ({ ref, title, path, isHome: !!opts.isHome, content: pageJson([n("Navbar", opts.nav || {}), ...sections, n("Footer", opts.footer || {})]) });
const contactPage = (extra = {}) => page("contact", "Contact", "/contact", [n("Hero", { layout: "center", tone: "soft", eyebrow: "Contact", heading: "We would love to hear from you", text: "Call, email or visit us. We reply within one working day.", primaryLabel: "", secondaryLabel: "" }), n("ContactInfo", { heading: "Reach us", mapQuery: "New Delhi", ...extra }), n("FormSection", {})]);
const menu = (refs) => [{ location: "primary", items: refs.map(([pageRef, label]) => ({ id: uid(), label, type: "page", pageRef })) }];

