const H = (layout, tone, eyebrow, heading, text, b1 = "", h1 = "", b2 = "", h2 = "") => n("Hero", { layout, tone, eyebrow, heading, text, primaryLabel: b1, primaryHref: h1, secondaryLabel: b2, secondaryHref: h2 });
