const PL = (heading, items, tone = "none") => n("PriceList", { heading, tone, eyebrow: "", text: "", items: items.map(([name, note, price]) => ({ name, note, price })) });
const TM = (heading, people, o = {}) => n("Team", { heading, eyebrow: "", text: "", tone: o.tone || "none", columns: o.cols || Math.min(4, people.length), items: people.map(([name, role]) => ({ name, role, photo: "" })) });
const TS = (heading, quotes, o = {}) => n("Testimonials", { heading, eyebrow: "", text: "", tone: o.tone || "soft", columns: o.cols || Math.min(3, quotes.length), items: quotes.map(([quote, name, role]) => ({ quote, name, role, photo: "" })) });
