/** Fill empty picture slots with the built-in artwork, so a fresh template looks finished. */
function decorate(pages, key = "") {
  // each template starts at a different picture, so two templates do not open with the same one
  const seed = [...key].reduce((sum, ch) => sum + ch.charCodeAt(0), 0);
  let scene = seed % 24, person = seed % 8;
  const art = () => `/wb-art/scene-${(scene++ % 24) + 1}.svg`;
  const face = () => `/wb-art/person-${(person++ % 8) + 1}.svg`;
  const fill = (node) => {
    const p = node.props || {};
    if (["Hero", "Split"].includes(node.type) && !p.image && p.layout !== "center") p.image = art();
    if (node.type === "Image" && !p.src) p.src = art();
    if (node.type === "ImageCard" && !p.image) p.image = art();
    if (node.type === "Gallery") p.items = (p.items || []).map((it) => (it.src ? it : { ...it, src: art() }));
    if (node.type === "Carousel") p.items = (p.items || []).map((it) => (it.image ? it : { ...it, image: art() }));
    if (["Team", "Testimonials"].includes(node.type)) p.items = (p.items || []).map((it) => (it.photo ? it : { ...it, photo: face() }));
    (node.children || []).forEach(fill);
  };
  pages.forEach((pg) => fill(pg.content.root));
  return pages;
}

/** The package the API installs: { key, theme, pages, menus }. */
export function buildTemplatePackage(key) {
  const tpl = SITE_TEMPLATES.find((t) => t.key === key) || SITE_TEMPLATES[SITE_TEMPLATES.length - 1];
  const built = tpl.build();
  return { key: tpl.key, theme: themeOf(tpl.preset), ...built, pages: decorate(built.pages, tpl.key) };
}
export const TEMPLATE_CATEGORIES = [...new Set(SITE_TEMPLATES.map((t) => t.category))];
